import{_ as t,o as i,c as e,ai as a}from"./chunks/framework.BxxKhjs3.js";const o="/pub-blog/assets/kimi-k2-6-hero.Br87030y.png",s="/pub-blog/assets/kimi-code-bench.ugNNIIDV.png",r="/pub-blog/assets/kimi-case-zig.C_VJjK49.png",d="/pub-blog/assets/kimi-case-exchange.DA-mBigi.png",l="/pub-blog/assets/image-20260421113951485.ti-J4v9s.png",h="/pub-blog/assets/wxcode.BIxKRB_A.png",_=JSON.parse('{"title":"你的 coding plan 套餐都下架了吧？试试新出的 Kimi K2.6","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/你的codingplan套餐都下架了吧，试试新出的kimi2.6/你的codingplan套餐都下架了吧，试试新出的kimi2.6.md","filePath":"AI人工智能/你的codingplan套餐都下架了吧，试试新出的kimi2.6/你的codingplan套餐都下架了吧，试试新出的kimi2.6.md","lastUpdated":1776742929000,"__rawMarkdown":"# 你的 coding plan 套餐都下架了吧？试试新出的 Kimi K2.6\\n\\n> 最近各大厂商的 coding plan 套餐纷纷下架，普通开发者该何去何从？\\n\\n最近发现一件挺扎心的事——各大云厂商的 coding plan 套餐正在陆续下架。\\n\\n之前用的阿里百炼套餐，40 块钱的续费入口已经没了，现在只剩 200 块/月的 PRO 套餐。智谱、MiniMax 这些也差不多，低价档基本消失殆尽。\\n\\n**这意味着什么？** 云厂商的\\"穷鬼套餐\\"时代可能真的结束了。\\n\\n作为普通开发者，眼下最现实的选择就是转向单一 AI 大模型的订阅套餐。而刚好，Kimi 在前几天推出了 **Kimi K2.6**，号称编程能力大幅提升。万少抱着尝鲜的心态，直接入了 199 元的 Allegretto 套餐，准备爆肝实测。\\n\\n---\\n\\n## Kimi K2.6 简介\\n\\nKimi K2.6 是 Kimi 最新发布的模型，主打三大能力：\\n\\n- **顶尖编程能力** —— 在 Terminal-Bench 2.0、SWE-Bench Pro 等基准测试中达到 SOTA 水平\\n- **长程任务执行** —— 支持 12+ 小时的连续执行，4,000+ 次工具调用\\n- **多智能体协作** —— Agent Swarm 架构支持 300 个子智能体同时执行 4,000 个协调步骤\\n\\n目前已在 Kimi 网页版、App、API 及 Kimi Code 中上线。\\n\\n![Kimi K2.6 官方介绍](assets/kimi-k2-6-hero.png)\\n\\n---\\n\\n### 长程编码能力大幅提升\\n\\n最让我心动的是它在**长程编码任务**上的表现。K2.6 不仅在 Python、Rust、Go 等主流语言上泛化能力很强，在前端、DevOps、性能优化等不同工程场景下也能稳定输出。\\n\\n官方自研了 **Kimi Code Bench** 基准测试，覆盖各类复杂端到端工程任务。从官方数据看，K2.6 相比 K2.5 提升显著：\\n\\n| 基准测试 | Kimi K2.6 | Kimi K2.5 | Claude Opus 4.6 | GPT-5.4 | Gemini 3.1 Pro |\\n|---------|-----------|-----------|-----------------|---------|----------------|\\n| Terminal-Bench 2.0 | **66.7** | 65.4* | 68.5 | — | 50.8 |\\n| SWE-Bench Pro | **58.6** | 57.7 | 54.2 | 53.4 | 50.7 |\\n| SWE-Bench Verified | **80.2** | — | 80.6 | 80.8 | 76.8 |\\n| LiveCodeBench (v6) | **89.6** | — | 91.7 | 88.8 | 85.0 |\\n\\n\\n\\n![Kimi Code Bench 基准测试对比](assets/kimi-code-bench.png)\\n\\n---\\n\\n#### 官方案例：用 Zig 语言本地部署 Qwen3.5\\n\\n官方举了一个相当硬核的例子——在 Mac 上用 **Zig** 语言（相当小众）本地部署并优化 Qwen3.5-0.8B 模型推理：\\n\\n| 指标 | 数据 |\\n|------|------|\\n| 工具调用次数 | **4,000+** |\\n| 连续执行时长 | **12 小时+** |\\n| 迭代优化轮数 | **14 轮** |\\n| 初始吞吐量 | ~15 tokens/秒 |\\n| 优化后吞吐量 | **~193 tokens/秒** |\\n| 相比 LM Studio | 快 **约 20%** |\\n\\n这个案例说明 Kimi K2.6 不是只能写几行脚本的\\"玩具\\"，而是能处理**持续执行、反复调试、长时间运行**的复杂工程任务。对需要爆肝搞项目的开发者来说，这个能力很有吸引力。\\n\\n#### 另一个硬核案例：优化 8 年老项目 exchange-core\\n\\nKimi K2.6 还自主改造了一个 8 年历史的开源金融撮合引擎 **exchange-core**。在 **13 小时**的执行过程中，模型迭代了 12 种优化策略，发起 1,000+ 次工具调用，精准修改了 4,000+ 行代码。最终实现了：\\n\\n- **中等吞吐量提升 185%**（从 0.43 提升到 1.24 MT/s）\\n- **性能吞吐量提升 133%**（从 1.23 提升到 2.86 MT/s）\\n\\n![Zig 部署 Qwen3.5 案例](assets/kimi-case-zig.png)\\n\\n![exchange-core 优化案例](assets/kimi-case-exchange.png)\\n\\n---\\n\\n### 企业级评价\\n\\nKimi K2.6 在多家企业的内部评测中获得了高度评价：\\n\\n- **CodeBuddy**：代码生成准确率提升 12%，长上下文稳定性提升 18%，工具调用成功率达到 **96.60%**\\n- **Vercel AI**：Next.js 基准测试提升 **50%+**，跻身平台顶尖模型行列\\n- **KiloClaw**：长上下文任务表现极佳，性价比突出\\n- **OpenCode**：任务分解和工具调用非常稳定，多步骤操作流畅\\n\\n---\\n\\n### 实际体验总结\\n\\n目前刚上手，初步感受如下：\\n\\n1. **长程任务稳定性不错** —— 不会像某些模型写到后面就开始\\"失忆\\"或跑偏\\n2. **Coding 场景确实是强项** —— 代码理解、多文件协作、debug 都比较在线\\n3. **199 元套餐性价比尚可** —— 对比现在动辄 200 元的\\"PRO 套餐\\"，Kimi 的定价还算友好\\n\\nKimi 目前的套餐分为四档：\\n\\n| 套餐 | 月费 | 定位 | 核心权益 |\\n|------|------|------|----------|\\n| Andante | ¥49 | 日常使用 | 基础 Agent 额度 |\\n| Moderato | ¥99 | 效率升级 | 2 倍 Agent 额度，Kimi Code 4 倍额度 |\\n| **Allegretto** | **¥199** | **专业优选** | **4 倍 Agent 额度，Agent 多任务并行，Kimi Code 20 倍额度** |\\n| Allegro | ¥699 | 全能尊享 | 10 倍 Agent 额度，Kimi Code 60 倍额度 |\\n\\n我选的是 **Allegretto（¥199/月）**，主要看重它的 Agent 多任务并行和 20 倍 Kimi Code 额度，对于日常开发来说够用了。\\n\\nKimi 套餐详情可查看[官方定价页面](https://www.kimi.com/membership/pricing)。\\n\\n---\\n\\n\\n\\n---\\n\\n## 如何接入和使用\\n\\n### Kimi Code\\n\\n#### 安装\\n\\n运行安装脚本即可完成安装。脚本会先安装 [uv](https://docs.astral.sh/uv/)（Python 包管理工具），再通过 uv 安装 Kimi Code CLI：\\n\\n\\n\\n```markdown\\n# Linux / macOS\\ncurl -LsSf https://code.kimi.com/install.sh | bash\\n```\\n\\n\\n\\n```markdown\\n# Windows (PowerShell)\\nInvoke-RestMethod https://code.kimi.com/install.ps1 | Invoke-Expression\\n```\\n\\n验证安装是否成功：\\n\\n\\n\\n```\\nkimi --version\\n```\\n\\n#### 第一次运行\\n\\n终端中输入 **kimi**\\n\\n> 执行登录\\n>\\n> /login\\n\\n执行后首先选择平台。推荐选择 Kimi Code，会自动打开浏览器进行 OAuth 授权；\\n\\n### claude code\\n\\nclaude code中也可以接入 kimi大模型，这里推荐试试 cc swtich方便切换\\n\\n![](assets/image-20260421113951485.png)\\n\\n\\n\\n## 写在最后\\n\\n如果你之前的 coding plan 套餐刚好到期或下架，Kimi K2.6 值得一试。建议先用网页版免费体验，觉得合适再决定是否购买套餐。\\n\\n后续万少会在实际项目中深度使用，有新的发现再和大家分享。也欢迎你在评论区聊聊：你现在的 AI 编程助手用的是什么？\\n\\n![](assets/wxcode.BIxKRB_A.png)\\n\\n---\\n\\n*本文部分数据参考自 [Kimi 官方博客](https://www.kimi.com/blog/kimi-k2-6)*"}'),p={name:"AI人工智能/你的codingplan套餐都下架了吧，试试新出的kimi2.6/你的codingplan套餐都下架了吧，试试新出的kimi2.6.md"};function g(c,n,m,u,k,b){return i(),e("div",null,[...n[0]||(n[0]=[a("",63)])])}const w=t(p,[["render",g]]);export{_ as __pageData,w as default};
